import {AIMessage} from '@langchain/core/messages';
import {CapabilityRegistry} from '../../../core/dist/index.js';
import {SqliteAgentRuns,SqliteAgentDefinitions,DurableAgentWorker,createConfiguredAgentRun} from '../../dist/index.js';
const [runPath,definitionPath,dataUrl]=process.argv.slice(2),scope={tenantId:'tenant',agentId:'operations'},runs=new SqliteAgentRuns(runPath),definitions=new SqliteAgentDefinitions(definitionPath),audit=[],registry=new CapabilityRegistry(event=>audit.push(event));let calls=0,principal;
try{
 registry.register({operationId:'lookup',method:'GET',path:'/lookup'},{authorize:context=>context.tenantId==='tenant'&&context.principalId==='service-account',validate:()=>true,execute:(_input,context)=>{calls++;principal=context.principalId;return {ok:true};}});
 const worker=new DurableAgentWorker({runs,definitions,workerId:'worker',leaseMs:3000,pollMs:25,authorizeStart:()=>true,execute:async(run,{signal,assertLease})=>{const configured=await createConfiguredAgentRun({definitions,tenantId:'tenant',agentId:'operations',expectedVersion:run.definitionVersion,bindings:[{operationId:'lookup',toolName:'lookup',description:'Read records'}],registry,authorizeRun:()=>true,authorizeCapability:()=>{assertLease();return true;},createModel:()=>{let turn=0;return {async invoke(){return ++turn===1?new AIMessage({content:'',tool_calls:[{id:'call',name:'lookup',args:{}}]}):new AIMessage('Done');}};}});let final;for await(const event of configured.run({threadId:'thread',runId:'one',messages:[{role:'user',content:'Check records'}]},{signal}))final=event;return final?.type==='RUN_FINISHED'?'succeeded':'uncertain';}});
 const publication=await fetch(dataUrl+'/application'),definition=await publication.json(),result=await worker.runOnce(scope,'one');process.send?.({status:result.status,publicationStatus:publication.status,publicationVersion:definition.version,page:definition.definition.pages[0]?.title,calls,principal,auditPrincipals:audit.map(event=>event.principalId)});
}catch(error){process.send?.({error:String(error)});process.exitCode=1;}finally{definitions.close();runs.close();}
